"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";

import { cn } from "@/lib/utils";
import { focusRing, wellInset } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Burnished Tabs root: owns which panel shows. */
const Tabs = TabsPrimitive.Root;

/**
 * Burnished TabsList: a row of pill labels pressed into a recessed well,
 * like a segmented switch cut into the page.
 */
const TabsList = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.List.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    data-slot="tabs-list"
    className={cn(
      "inline-flex h-11 items-center gap-1 rounded-full p-1 text-muted-foreground",
      wellInset,
      className,
    )}
    {...props}
  />
));
TabsList.displayName = "TabsList";

/**
 * Burnished TabsTrigger: muted semibold text in a pill. The active tab
 * rises out of the well as a graphite bevel in full ink.
 */
const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TabsPrimitive.Tab.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Tab
    ref={ref}
    data-slot="tabs-trigger"
    className={cn(
      "inline-flex h-9 shrink-0 items-center justify-center gap-1.5 whitespace-nowrap rounded-full px-4",
      "text-sm font-semibold tracking-[0.016em] text-muted-foreground",
      "transition-[box-shadow,color] duration-base ease-(--ease-out)",
      "[@media(hover:hover)_and_(pointer:fine)]:hover:text-foreground",
      "data-[active]:bg-(image:--fill-raised) data-[active]:text-foreground data-[active]:shadow-(--bevel-raised)",
      focusRing,
      "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
      "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
      className,
    )}
    {...props}
  />
));
TabsTrigger.displayName = "TabsTrigger";

/** Burnished TabsContent: the active panel, set below the tab row. */
const TabsContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Panel
    ref={ref}
    data-slot="tabs-content"
    className={cn("mt-4 rounded-lg", focusRing, className)}
    {...props}
  />
));
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };
